import React, { useState, useEffect } from 'react';
import { CheckCircleIcon, ExclamationTriangleIcon, InformationCircleIcon, DocumentDuplicateIcon, ArrowTopRightOnSquareIcon } from '@heroicons/react/24/outline';
import { useNotification } from '../../hooks/useNotification';
import api from '../../services/api';

const CompletionStep = ({ domainId, data, onChange, errors, onPrev, canGoBack, saving }) => {
  const [verificationStatus, setVerificationStatus] = useState(null);
  const [isVerifying, setIsVerifying] = useState(false);
  const [showInstructions, setShowInstructions] = useState(true);
  const { showNotification } = useNotification();

  // Resumen de configuración
  const configSummary = {
    spf: {
      record: data.spfRecord || '',
      configured: !!data.spfRecord
    },
    dkim: {
      record: data.dkimRecord || '',
      selector: data.dkimSelector || '',
      configured: !!data.dkimRecord
    },
    dmarc: {
      record: data.dmarcRecord || '',
      policy: data.dmarcPolicy || 'none',
      configured: !!data.dmarcRecord
    }
  };

  const allConfigured = configSummary.spf.configured && 
                       configSummary.dkim.configured && 
                       configSummary.dmarc.configured;

  useEffect(() => {
    // Verificar automáticamente si todos los registros están configurados
    if (allConfigured && !verificationStatus) {
      handleVerifyDNS();
    }
  }, [allConfigured]);

  const handleVerifyDNS = async () => {
    if (!domainId) {
      showNotification('ID de dominio no disponible', 'error');
      return;
    }

    setIsVerifying(true);
    try {
      const response = await api.post(`/api/dns-verification/${domainId}/verify/`);

      if (response.data.task_id) {
        // Esperar un momento y luego verificar el estado
        setTimeout(() => {
          checkVerificationStatus(response.data.task_id);
        }, 3000);
      }
    } catch (error) {
      console.error('Error starting DNS verification:', error);
      showNotification('Error al iniciar la verificación DNS', 'error');
      setIsVerifying(false);
    }
  };

  const checkVerificationStatus = async (taskId) => {
    try {
      const response = await api.get(`/api/dns-verification/${domainId}/status/`);
      setVerificationStatus(response.data);
      setIsVerifying(false);

      if (response.data.status === 'completed') {
        const hasErrors = response.data.results?.some(result => !result.valid);
        if (hasErrors) {
          showNotification('Algunos registros DNS no se pudieron verificar', 'warning');
        } else {
          showNotification('¡Todos los registros DNS verificados correctamente!', 'success');
        }
      }
    } catch (error) {
      console.error('Error checking verification status:', error);
      setIsVerifying(false);
    }
  };

  const copyToClipboard = async (text, label) => {
    try {
      await navigator.clipboard.writeText(text);
      showNotification(`${label} copiado al portapapeles`, 'success');
    } catch (error) {
      console.error('Error copying to clipboard:', error);
      showNotification('Error al copiar al portapapeles', 'error');
    }
  };

  const getRecordStatus = (recordType) => {
    if (!verificationStatus || !verificationStatus.results) {
      return 'pending';
    }

    const result = verificationStatus.results.find(r => r.record_type === recordType.toUpperCase());
    return result ? (result.valid ? 'valid' : 'invalid') : 'pending';
  };

  const getStatusIcon = (status) => {
    switch (status) {
      case 'valid':
        return <CheckCircleIcon className="h-5 w-5 text-green-500" />;
      case 'invalid':
        return <ExclamationTriangleIcon className="h-5 w-5 text-red-500" />;
      default:
        return <div className="h-5 w-5 border-2 border-gray-300 border-t-primary-600 rounded-full animate-spin" />;
    }
  };

  const getStatusText = (status) => {
    switch (status) {
      case 'valid':
        return 'Verificado';
      case 'invalid':
        return 'Error';
      default:
        return 'Pendiente';
    }
  };

  const getStatusColor = (status) => {
    switch (status) {
      case 'valid':
        return 'text-green-600';
      case 'invalid':
        return 'text-red-600';
      default:
        return 'text-gray-600';
    }
  };

  return (
    <div className="space-y-6">
      {/* Encabezado de finalización */}
      <div className="text-center">
        <div className="mx-auto flex items-center justify-center h-12 w-12 rounded-full bg-green-100">
          <CheckCircleIcon className="h-6 w-6 text-green-600" />
        </div>
        <h2 className="mt-4 text-2xl font-bold text-gray-900">
          ¡Configuración DMARC Completada!
        </h2>
        <p className="mt-2 text-sm text-gray-600">
          Has configurado exitosamente SPF, DKIM y DMARC para tu dominio.
        </p>
      </div>

      {/* Resumen de configuración */}
      <div className="bg-white border border-gray-200 rounded-lg p-6">
        <h3 className="text-lg font-medium text-gray-900 mb-4">Resumen de Configuración</h3>

        <div className="space-y-4">
          {/* SPF */}
          <div className="flex items-start justify-between p-4 bg-gray-50 rounded-lg">
            <div className="flex-1">
              <div className="flex items-center justify-between mb-2">
                <h4 className="text-sm font-medium text-gray-900">Registro SPF</h4>
                <div className="flex items-center space-x-2">
                  {getStatusIcon(getRecordStatus('spf'))}
                  <span className={`text-sm font-medium ${getStatusColor(getRecordStatus('spf'))}`}>
                    {getStatusText(getRecordStatus('spf'))}
                  </span>
                </div>
              </div>
              {configSummary.spf.configured ? (
                <div className="font-mono text-xs bg-white border border-gray-200 rounded p-2 break-all">
                  {configSummary.spf.record}
                </div>
              ) : (
                <p className="text-sm text-gray-500">No configurado</p>
              )}
            </div>
            {configSummary.spf.configured && (
              <button
                onClick={() => copyToClipboard(configSummary.spf.record, 'Registro SPF')}
                className="ml-3 text-primary-600 hover:text-primary-800"
              >
                <DocumentDuplicateIcon className="h-4 w-4" />
              </button>
            )}
          </div>

          {/* DKIM */}
          <div className="flex items-start justify-between p-4 bg-gray-50 rounded-lg">
            <div className="flex-1">
              <div className="flex items-center justify-between mb-2">
                <h4 className="text-sm font-medium text-gray-900">Registro DKIM</h4>
                <div className="flex items-center space-x-2">
                  {getStatusIcon(getRecordStatus('dkim'))}
                  <span className={`text-sm font-medium ${getStatusColor(getRecordStatus('dkim'))}`}>
                    {getStatusText(getRecordStatus('dkim'))}
                  </span>
                </div>
              </div>
              {configSummary.dkim.configured ? (
                <div>
                  <div className="text-xs text-gray-600 mb-1">
                    Selector: {configSummary.dkim.selector}
                  </div>
                  <div className="font-mono text-xs bg-white border border-gray-200 rounded p-2 break-all">
                    {configSummary.dkim.record}
                  </div>
                </div>
              ) : (
                <p className="text-sm text-gray-500">No configurado</p>
              )}
            </div>
            {configSummary.dkim.configured && (
              <button
                onClick={() => copyToClipboard(configSummary.dkim.record, 'Registro DKIM')}
                className="ml-3 text-primary-600 hover:text-primary-800"
              >
                <DocumentDuplicateIcon className="h-4 w-4" />
              </button>
            )}
          </div>

          {/* DMARC */}
          <div className="flex items-start justify-between p-4 bg-gray-50 rounded-lg">
            <div className="flex-1">
              <div className="flex items-center justify-between mb-2">
                <h4 className="text-sm font-medium text-gray-900">Registro DMARC</h4>
                <div className="flex items-center space-x-2">
                  {getStatusIcon(getRecordStatus('dmarc'))}
                  <span className={`text-sm font-medium ${getStatusColor(getRecordStatus('dmarc'))}`}>
                    {getStatusText(getRecordStatus('dmarc'))}
                  </span>
                </div>
              </div>
              {configSummary.dmarc.configured ? (
                <div>
                  <div className="text-xs text-gray-600 mb-1">
                    Política: {configSummary.dmarc.policy}
                  </div>
                  <div className="font-mono text-xs bg-white border border-gray-200 rounded p-2 break-all">
                    {configSummary.dmarc.record}
                  </div>
                </div>
              ) : (
                <p className="text-sm text-gray-500">No configurado</p>
              )}
            </div>
            {configSummary.dmarc.configured && (
              <button
                onClick={() => copyToClipboard(configSummary.dmarc.record, 'Registro DMARC')}
                className="ml-3 text-primary-600 hover:text-primary-800"
              >
                <DocumentDuplicateIcon className="h-4 w-4" />
              </button>
            )}
          </div>
        </div>
      </div>

      {/* Verificación DNS */}
      <div className="bg-white border border-gray-200 rounded-lg p-6">
        <div className="flex items-center justify-between mb-4">
          <h3 className="text-lg font-medium text-gray-900">Verificación DNS</h3>
          <button
            onClick={handleVerifyDNS}
            disabled={isVerifying || !allConfigured}
            className="inline-flex items-center px-3 py-2 border border-transparent text-sm leading-4 font-medium rounded-md text-white bg-primary-600 hover:bg-primary-700 focus:outline-none focus:ring-2 focus:ring-offset-2 focus:ring-primary-500 disabled:opacity-50 disabled:cursor-not-allowed"
          >
            {isVerifying ? (
              <>
                <div className="animate-spin -ml-1 mr-2 h-4 w-4 border-2 border-white border-t-transparent rounded-full" />
                Verificando...
              </>
            ) : (
              'Verificar Registros'
            )}
          </button>
        </div>

        {!allConfigured ? (
          <div className="bg-yellow-50 border border-yellow-200 rounded-lg p-4">
            <div className="flex">
              <ExclamationTriangleIcon className="h-5 w-5 text-yellow-400 flex-shrink-0" />
              <div className="ml-3">
                <h4 className="text-sm font-medium text-yellow-800">
                  Configuración Incompleta
                </h4>
                <p className="mt-1 text-sm text-yellow-700">
                  Completa la configuración de todos los registros antes de verificar.
                </p>
              </div>
            </div>
          </div>
        ) : verificationStatus ? (
          <div className="space-y-3">
            {verificationStatus.results?.map((result, index) => (
              <div key={index} className={`
                flex items-center justify-between p-3 rounded-lg border
                ${result.valid 
                  ? 'bg-green-50 border-green-200' 
                  : 'bg-red-50 border-red-200'
                }
              `}>
                <div className="flex items-center">
                  {result.valid ? (
                    <CheckCircleIcon className="h-5 w-5 text-green-500 mr-3" />
                  ) : (
                    <ExclamationTriangleIcon className="h-5 w-5 text-red-500 mr-3" />
                  )}
                  <div>
                    <div className="text-sm font-medium text-gray-900">
                      {result.record_type}
                    </div>
                    {result.error && (
                      <div className="text-xs text-red-600">
                        {result.error}
                      </div>
                    )}
                  </div>
                </div>
                <span className={`
                  inline-flex items-center px-2.5 py-0.5 rounded-full text-xs font-medium
                  ${result.valid 
                    ? 'bg-green-100 text-green-800' 
                    : 'bg-red-100 text-red-800'
                  }
                `}>
                  {result.valid ? 'Válido' : 'Error'}
                </span>
              </div>
            ))}
          </div>
        ) : (
          <div className="text-center py-4">
            <p className="text-sm text-gray-500">
              Haz clic en "Verificar Registros" para comprobar la configuración DNS.
            </p>
          </div>
        )}
      </div>

      {/* Instrucciones de implementación */}
      {showInstructions && (
        <div className="bg-blue-50 border border-blue-200 rounded-lg p-6">
          <div className="flex items-start">
            <div className="flex-shrink-0">
              <InformationCircleIcon className="h-5 w-5 text-blue-400" />
            </div>
            <div className="ml-3 flex-1">
              <div className="flex items-center justify-between">
                <h3 className="text-sm font-medium text-blue-800">
                  Instrucciones de Implementación
                </h3>
                <button
                  onClick={() => setShowInstructions(false)}
                  className="text-blue-600 hover:text-blue-800 text-sm"
                >
                  Ocultar
                </button>
              </div>
              <div className="mt-2 text-sm text-blue-700">
                <ol className="list-decimal list-inside space-y-2">
                  <li>
                    <strong>Accede a tu proveedor DNS</strong> (donde gestionas los registros de tu dominio)
                  </li>
                  <li>
                    <strong>Crea los registros TXT</strong> con los valores mostrados arriba
                  </li>
                  <li>
                    <strong>Espera la propagación DNS</strong> (puede tomar hasta 24-48 horas)
                  </li>
                  <li>
                    <strong>Verifica los registros</strong> usando el botón "Verificar Registros"
                  </li>
                  <li>
                    <strong>Monitorea los reportes DMARC</strong> que llegarán a tu email configurado
                  </li>
                </ol>

                <div className="mt-4 p-3 bg-blue-100 rounded-md">
                  <p className="text-sm font-medium text-blue-800 mb-1">
                    💡 Consejo Importante:
                  </p>
                  <p className="text-sm text-blue-700">
                    Si configuraste la política DMARC como "none", revisa los reportes durante
                    al menos 2 semanas antes de cambiar a "quarantine" o "reject".
                  </p>
                </div>
              </div>
            </div>
          </div>
        </div>
      )}

      {/* Próximos pasos */}
      <div className="bg-white border border-gray-200 rounded-lg p-6">
        <h3 className="text-lg font-medium text-gray-900 mb-4">Próximos Pasos</h3>

        <div className="space-y-3">
          <div className="flex items-start">
            <div className="flex-shrink-0 w-6 h-6 bg-primary-100 rounded-full flex items-center justify-center mr-3 mt-0.5">
              <span className="text-xs font-medium text-primary-600">1</span>
            </div>
            <div>
              <h4 className="text-sm font-medium text-gray-900">Implementar Registros DNS</h4>
              <p className="text-sm text-gray-600">
                Añade los registros TXT generados a tu proveedor DNS.
              </p>
            </div>
          </div>

          <div className="flex items-start">
            <div className="flex-shrink-0 w-6 h-6 bg-primary-100 rounded-full flex items-center justify-center mr-3 mt-0.5">
              <span className="text-xs font-medium text-primary-600">2</span>
            </div>
            <div>
              <h4 className="text-sm font-medium text-gray-900">Monitorear Reportes</h4>
              <p className="text-sm text-gray-600">
                Revisa los reportes DMARC que llegarán a tu email para identificar problemas.
              </p>
            </div>
          </div>

          <div className="flex items-start">
            <div className="flex-shrink-0 w-6 h-6 bg-primary-100 rounded-full flex items-center justify-center mr-3 mt-0.5">
              <span className="text-xs font-medium text-primary-600">3</span>
            </div>
            <div>
              <h4 className="text-sm font-medium text-gray-900">Ajustar Políticas</h4>
              <p className="text-sm text-gray-600">
                Después de 2 semanas de monitoreo, considera endurecer la política DMARC.
              </p>
            </div>
          </div>

          <div className="flex items-start">
            <div className="flex-shrink-0 w-6 h-6 bg-primary-100 rounded-full flex items-center justify-center mr-3 mt-0.5">
              <span className="text-xs font-medium text-primary-600">4</span>
            </div>
            <div>
              <h4 className="text-sm font-medium text-gray-900">Configurar Alertas</h4>
              <p className="text-sm text-gray-600">
                Usa el panel de control para configurar alertas automáticas.
              </p>
            </div>
          </div>
        </div>
      </div>

      {/* Enlaces útiles */}
      <div className="bg-gray-50 border border-gray-200 rounded-lg p-6">
        <h3 className="text-lg font-medium text-gray-900 mb-4">Enlaces Útiles</h3>

        <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
          <a
            href="https://mxtoolbox.com/dmarc.aspx"
            target="_blank"
            rel="noopener noreferrer"
            className="flex items-center p-3 border border-gray-200 rounded-lg hover:bg-white transition-colors"
          >
            <ArrowTopRightOnSquareIcon className="h-5 w-5 text-gray-400 mr-3" />
            <div>
              <div className="text-sm font-medium text-gray-900">MXToolbox DMARC</div>
              <div className="text-xs text-gray-600">Verificar registros DMARC</div>
            </div>
          </a>

          <a
            href="https://dmarcian.com/dmarc-inspector/"
            target="_blank"
            rel="noopener noreferrer"
            className="flex items-center p-3 border border-gray-200 rounded-lg hover:bg-white transition-colors"
          >
            <ArrowTopRightOnSquareIcon className="h-5 w-5 text-gray-400 mr-3" />
            <div>
              <div className="text-sm font-medium text-gray-900">DMARC Inspector</div>
              <div className="text-xs text-gray-600">Analizar configuración DMARC</div>
            </div>
          </a>

          <a
            href="https://www.mail-tester.com/"
            target="_blank"
            rel="noopener noreferrer"
            className="flex items-center p-3 border border-gray-200 rounded-lg hover:bg-white transition-colors"
          >
            <ArrowTopRightOnSquareIcon className="h-5 w-5 text-gray-400 mr-3" />
            <div>
              <div className="text-sm font-medium text-gray-900">Mail Tester</div>
              <div className="text-xs text-gray-600">Probar entrega de correo</div>
            </div>
          </a>

          <a
            href="https://dmarc.org/"
            target="_blank"
            rel="noopener noreferrer"
            className="flex items-center p-3 border border-gray-200 rounded-lg hover:bg-white transition-colors"
          >
            <ArrowTopRightOnSquareIcon className="h-5 w-5 text-gray-400 mr-3" />
            <div>
              <div className="text-sm font-medium text-gray-900">DMARC.org</div>
              <div className="text-xs text-gray-600">Documentación oficial</div>
            </div>
          </a>
        </div>
      </div>

      {/* Botones de navegación */}
      <div className="flex justify-between pt-6">
        <button
          onClick={onPrev}
          disabled={!canGoBack}
          className="inline-flex items-center px-4 py-2 border border-gray-300 shadow-sm text-sm font-medium rounded-md text-gray-700 bg-white hover:bg-gray-50 focus:outline-none focus:ring-2 focus:ring-offset-2 focus:ring-primary-500 disabled:opacity-50 disabled:cursor-not-allowed"
        >
          Anterior
        </button>

        <button
          onClick={() => window.location.href = '/dashboard'}
          className="inline-flex items-center px-4 py-2 border border-transparent text-sm font-medium rounded-md shadow-sm text-white bg-green-600 hover:bg-green-700 focus:outline-none focus:ring-2 focus:ring-offset-2 focus:ring-green-500"
        >
          Ir al Dashboard
        </button>
      </div>
    </div>
  );
};

export default CompletionStep;
